import {graphicsQuality,setGraphicsQuality} from './graphics.js';
const destinations=[['singularity','Black holes'],['relativity-lab','Relativity lab'],['universe','Universe atelier'],['explore','Planetary observatory'],['journey','Six-world flyby'],['solar-system','Orbital engine'],['gravity-studio','Gravity dynamics'],['field-lab','World comparisons'],['expeditions','Expedition studio'],['data-lab','Planetary data'],['light-lab','Transmission control']];
export function setupObservatoryUI(){
 if(document.querySelector('#observatory-directory'))return;const header=document.querySelector('.header'),nav=header.querySelector('nav'),link=document.createElement('a');link.href='#universe';link.textContent='Universe';nav.querySelector('a').after(link);
 const directory=document.createElement('details');directory.id='observatory-directory';directory.innerHTML='<summary>Explore <span>↗</span></summary><div class="directory-panel"><span>CHOOSE YOUR INSTRUMENT</span>'+destinations.map(([id,name],i)=>'<a href="#'+id+'"><small>'+String(i+1).padStart(2,'0')+'</small>'+name+'<b>↗</b></a>').join('')+'</div>';header.append(directory);
 const quality=document.createElement('label');quality.className='global-quality';quality.innerHTML='<span>GRAPHICS</span><select id="graphics-quality" aria-label="Graphics quality"><option value="auto">Auto</option><option value="efficient">Efficient</option><option value="ultra">Ultra</option><option value="4k">4K</option></select>';header.append(quality);quality.querySelector('select').value=graphicsQuality();quality.querySelector('select').onchange=e=>setGraphicsQuality(e.target.value);setGraphicsQuality(graphicsQuality());
 directory.addEventListener('click',e=>{if(e.target.closest('a'))directory.open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape')directory.open=false});document.addEventListener('pointerdown',e=>{if(!directory.contains(e.target))directory.open=false});
 const bar=document.createElement('i');bar.id='reading-progress';header.append(bar);let queued=false;function update(){queued=false;const y=window.scrollY,max=document.documentElement.scrollHeight-window.innerHeight;bar.style.width=(max>0?y/max*100:0)+'%';let current='singularity';for(const [id] of destinations){const el=document.getElementById(id);if(el){const r=el.getBoundingClientRect();if(r.top<=150&&r.bottom>150)current=id;}}nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+current));}
 window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});
 const brand=header.querySelector('.brand-caption');if(brand)brand.innerHTML='INDEPENDENT<br>OBSERVATORY / 10';
 const palette=document.querySelector('#command-search');if(palette)palette.placeholder='Find a world, experiment, or instrument…';
}
